using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

var topic = args.Length > 0 ? string.Join(' ', args) : "the impact of quantum computing on cryptography";

Console.WriteLine($"Research Agent Starting...");
Console.WriteLine($"Researching topic: {topic}");
Console.WriteLine(new string('-', 60));

// Configure the chat client with tool support
var openAiClient = new OpenAIClient(Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "sk-placeholder");
IChatClient chatClient = openAiClient
    .GetChatClient("gpt-4o")
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// Note-taking state
var notes = new List<string>();

[Description("Search the web for information on a query. Returns relevant search results.")]
string WebSearch(string query)
{
    Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");
    // Simulated web search results for demonstration
    return $"""
        Search results for "{query}":
        1. Overview article discussing key concepts and recent developments related to {query}.
        2. Academic paper analyzing the current state and future trajectory of {query}.
        3. Industry report with statistics and expert opinions on {query}.
        Summary: Multiple authoritative sources found covering definitions, recent breakthroughs, challenges, and future outlook for {query}.
        """;
}

[Description("Save a research note for later summarization. Use this to record key findings.")]
string TakeNote(string note)
{
    notes.Add(note);
    Console.WriteLine($"  [Tool] Note saved ({notes.Count} total)");
    return $"Note saved successfully. You now have {notes.Count} note(s).";
}

[Description("Retrieve all saved research notes.")]
string GetNotes()
{
    if (notes.Count == 0)
        return "No notes have been saved yet.";
    return string.Join("\n\n", notes.Select((n, i) => $"Note {i + 1}: {n}"));
}

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(WebSearch),
        AIFunctionFactory.Create(TakeNote),
        AIFunctionFactory.Create(GetNotes)
    ]
};

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information (perform 2-3 searches with different angles)
        2. Taking notes on key findings as you go
        3. Finally, providing a comprehensive summary of your research

        Always use the tools available to you. Search, take notes, then summarize.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

Console.WriteLine("\nAgent is researching...\n");

var response = await chatClient.GetResponseAsync(messages, chatOptions);

Console.WriteLine(new string('-', 60));
Console.WriteLine("RESEARCH SUMMARY");
Console.WriteLine(new string('-', 60));
Console.WriteLine(response.Text);
Console.WriteLine(new string('-', 60));
Console.WriteLine($"\nResearch complete. {notes.Count} note(s) were recorded during research.");

